new file mode 100644
index 0000000..a1b2c3d
--- /dev/null
+++ b/src/sanitize-svg.js
@@ -0,0 +1,52 @@
+/**
+ * Sanitize an SVG DOM to prevent DOM-based XSS attacks.
+ * Removes <script> elements, event handler attributes, and
+ * dangerous URL schemes (e.g. javascript:) from href/src attributes.
+ * @param {Document} dom - The parsed SVG DOM document.
+ */
+const sanitizeSVG = function (dom) {
+    // Remove all <script> elements
+    const scripts = dom.getElementsByTagName('script');
+    // getElementsByTagName returns a live NodeList, so always remove index 0
+    while (scripts.length > 0) {
+        scripts[0].parentNode.removeChild(scripts[0]);
+    }
+
+    // Walk all elements and remove dangerous attributes
+    const allElements = dom.getElementsByTagName('*');
+    for (let i = 0; i < allElements.length; i++) {
+        const el = allElements[i];
+        const attrs = el.attributes;
+        // Iterate backwards because we may remove attributes during iteration
+        for (let j = attrs.length - 1; j >= 0; j--) {
+            const attrName = attrs[j].name;
+            const attrValue = attrs[j].value;
+
+            // Remove event handler attributes (onload, onclick, onerror, etc.)
+            if (attrName.length > 2 && attrName.substring(0, 2).toLowerCase() === 'on') {
+                el.removeAttribute(attrName);
+                continue;
+            }
+
+            // Remove dangerous URL schemes from link/reference attributes
+            const lowerName = attrName.toLowerCase();
+            if (lowerName === 'href' || lowerName === 'xlink:href' ||
+                lowerName === 'src' || lowerName === 'action' ||
+                lowerName === 'formaction' || lowerName === 'poster') {
+                const trimmed = attrValue.trim().toLowerCase();
+                // Block javascript: and data:text/html URIs
+                if (trimmed.indexOf('javascript:') === 0 ||
+                    trimmed.indexOf('data:text/html') === 0) {
+                    el.removeAttribute(attrName);
+                }
+            }
+
+            // Remove <a> or other elements with xlink:href using javascript:
+            if (lowerName === 'style') {
+                // Block expression() and url(javascript:...) in inline styles
+                const styleVal = attrValue.toLowerCase();
+                if (styleVal.indexOf('expression') !== -1 ||
+                    styleVal.indexOf('javascript:') !== -1) {
+                    el.removeAttribute(attrName);
+                }
+            }
+        }
+    }
+};
+
+module.exports = sanitizeSVG;
