 use serde::Deserialize;
+use crate::error::{Error, Result};
+use crate::quote::QeReport;

 #[derive(Debug, Deserialize)]
 pub struct QeIdentity {
+    #[serde(rename = "enclaveIdentity")]
     pub enclave_identity: EnclaveIdentity,
 }

@@ -12,6 +15,14 @@ pub struct EnclaveIdentity {
     pub attributes: String,
     #[serde(rename = "attributesMask")]
     pub attributes_mask: String,
+    #[serde(rename = "miscselect")]
+    pub miscselect: String,
+    #[serde(rename = "miscselectMask")]
+    pub miscselect_mask: String,
+    pub mrsigner: String,
+    pub isvprodid: u16,
 }

+/// Verify that the QE Report matches the policy constraints defined in the
+/// (already signature-verified) QE Identity. This prevents an attacker from
+/// using a forged or mismatched Quoting Enclave.
+pub fn verify_qe_report_against_identity(
+    qe_report: &QeReport,
+    qe_identity: &QeIdentity,
+) -> Result<()> {
+    let identity = &qe_identity.enclave_identity;
+
+    // Verify MRSIGNER — ensures the QE was signed by the expected authority (Intel)
+    let expected_mrsigner = hex::decode(&identity.mrsigner)
+        .map_err(|e| Error::ParseError(format!("Invalid mrsigner hex: {}", e)))?;
+    if qe_report.mrsigner.as_ref() != expected_mrsigner.as_slice() {
+        return Err(Error::QeIdentityMismatch(
+            "QE Report MRSIGNER does not match QE Identity".into(),
+        ));
+    }
+
+    // Verify ISV Product ID
+    if qe_report.isv_prod_id != identity.isvprodid {
+        return Err(Error::QeIdentityMismatch(
+            "QE Report ISV Product ID does not match QE Identity".into(),
+        ));
+    }
+
+    // Verify ATTRIBUTES with mask
+    let expected_attributes = hex::decode(&identity.attributes)
+        .map_err(|e| Error::ParseError(format!("Invalid attributes hex: {}", e)))?;
+    let attributes_mask = hex::decode(&identity.attributes_mask)
+        .map_err(|e| Error::ParseError(format!("Invalid attributes mask hex: {}", e)))?;
+    for i in 0..expected_attributes.len().min(qe_report.attributes.len()) {
+        if (qe_report.attributes[i] & attributes_mask[i])
+            != (expected_attributes[i] & attributes_mask[i])
+        {
+            return Err(Error::QeIdentityMismatch(
+                "QE Report attributes do not match QE Identity policy".into(),
+            ));
+        }
+    }
+
+    // Verify MISCSELECT with mask
+    let expected_miscselect = u32::from_str_radix(&identity.miscselect, 16)
+        .map_err(|e| Error::ParseError(format!("Invalid miscselect hex: {}", e)))?;
+    let miscselect_mask = u32::from_str_radix(&identity.miscselect_mask, 16)
+        .map_err(|e| Error::ParseError(format!("Invalid miscselect mask hex: {}", e)))?;
+    if (qe_report.miscselect & miscselect_mask)
+        != (expected_miscselect & miscselect_mask)
+    {
+        return Err(Error::QeIdentityMismatch(
+            "QE Report miscselect does not match QE Identity policy".into(),
+        ));
+    }
+
+    Ok(())
+}
