+namespace MongoDB\Driver;
+
+use stdClass;
+
+/**
+ * Redacts sensitive command documents to prevent authentication data
+ * from being exposed through command monitoring events.
+ *
+ * @internal
+ * @see https://jira.mongodb.org/browse/PHPC-1859
+ */
+final class CommandRedactor
+{
+    /** @var array<string, true> */
+    private const SENSITIVE_COMMANDS = [
+        'authenticate' => true,
+        'saslStart' => true,
+        'saslContinue' => true,
+        'getnonce' => true,
+        'createUser' => true,
+        'updateUser' => true,
+        'copydbgetnonce' => true,
+        'copydbsaslstart' => true,
+        'copydb' => true,
+    ];
+
+    /**
+     * Redacts the command document if the command is security-sensitive.
+     *
+     * For sensitive commands, only the command name and its first value
+     * are preserved; all other fields (which may contain credentials,
+     * tokens, or passwords) are stripped.
+     *
+     * @param string       $commandName     The name of the command
+     * @param array|object $commandDocument The command document to redact
+     * @return array|object The redacted (or original) command document
+     */
+    public static function redact(string $commandName, $commandDocument)
+    {
+        if (! isset(self::SENSITIVE_COMMANDS[$commandName])) {
+            return $commandDocument;
+        }
+
+        $value = is_object($commandDocument)
+            ? ($commandDocument->{$commandName} ?? 1)
+            : ($commandDocument[$commandName] ?? 1);
+
+        return is_object($commandDocument)
+            ? (object) [$commandName => $value]
+            : [$commandName => $value];
+    }
+}
