+package org.apache.streampipes.commons.validator;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.UnknownHostException;
+
+public class UrlValidator {
+
+  /**
+   * Validates a URL to prevent Server-Side Request Forgery (SSRF) attacks.
+   * Ensures the URL uses http/https scheme and does not resolve to internal/private addresses.
+   *
+   * @param url the URL to validate
+   * @throws IllegalArgumentException if the URL is invalid or resolves to an internal address
+   */
+  public static void validateUrl(String url) throws IllegalArgumentException {
+    if (url == null || url.trim().isEmpty()) {
+      throw new IllegalArgumentException("URL must not be null or empty");
+    }
+
+    URI uri;
+    try {
+      uri = new URI(url);
+    } catch (Exception e) {
+      throw new IllegalArgumentException("Invalid URL format: " + e.getMessage());
+    }
+
+    String scheme = uri.getScheme();
+    if (scheme == null || (!scheme.equalsIgnoreCase("http") && !scheme.equalsIgnoreCase("https"))) {
+      throw new IllegalArgumentException("URL scheme must be http or https");
+    }
+
+    String host = uri.getHost();
+    if (host == null || host.trim().isEmpty()) {
+      throw new IllegalArgumentException("URL must contain a valid host");
+    }
+
+    // Block localhost and common internal hostnames
+    if (host.equalsIgnoreCase("localhost")
+        || host.equalsIgnoreCase("127.0.0.1")
+        || host.equalsIgnoreCase("::1")
+        || host.equalsIgnoreCase("0.0.0.0")) {
+      throw new IllegalArgumentException("URL must not point to localhost");
+    }
+
+    // Resolve hostname and check for internal/private IP addresses
+    try {
+      InetAddress[] addresses = InetAddress.getAllByName(host);
+      for (InetAddress address : addresses) {
+        if (address.isLoopbackAddress()
+            || address.isLinkLocalAddress()
+            || address.isSiteLocalAddress()
+            || address.isAnyLocalAddress()
+            || address.isMulticastAddress()
+            || isPrivateNetwork(address)) {
+          throw new IllegalArgumentException(
+              "URL must not resolve to an internal or private network address");
+        }
+      }
+    } catch (UnknownHostException e) {
+      throw new IllegalArgumentException("Unable to resolve host: " + host);
+    }
+  }
+
+  private static boolean isPrivateNetwork(InetAddress address) {
+    byte[] bytes = address.getAddress();
+    if (bytes.length == 4) {
+      // Check for 100.64.0.0/10 (Carrier-grade NAT)
+      if (bytes[0] == 100 && (bytes[1] & 0xC0) == 64) {
+        return true;
+      }
+      // Check for 192.0.0.0/24 (IETF Protocol Assignments)
+      if (bytes[0] == (byte) 192 && bytes[1] == 0 && bytes[2] == 0) {
+        return true;
+      }
+      // Check for 198.18.0.0/15 (Benchmarking)
+      if (bytes[0] == (byte) 198 && (bytes[1] & 0xFE) == 18) {
+        return true;
+      }
+    }
+    return false;
+  }
+}
