+/// Resource limits for the WebAssembly interpreter to prevent denial of service
+/// through resource exhaustion (CWE-400).
+public struct Limits: Sendable {
+    /// Maximum number of WebAssembly memory pages (each page is 64 KiB).
+    /// The WebAssembly specification allows up to 65,536 pages (4 GiB).
+    /// Default is 256 pages (16 MiB).
+    public var maxMemoryPages: UInt32
+
+    /// Maximum depth of the call stack to prevent stack overflow.
+    /// Default is 1,000.
+    public var maxCallStackDepth: Int
+
+    /// Maximum number of instructions to execute before aborting.
+    /// Set to 0 for unlimited execution. Default is 10,000,000.
+    public var maxExecutionSteps: Int
+
+    /// Default resource limits suitable for most use cases.
+    public static let `default` = Limits()
+
+    public init(
+        maxMemoryPages: UInt32 = 256,
+        maxCallStackDepth: Int = 1_000,
+        maxExecutionSteps: Int = 10_000_000
+    ) {
+        self.maxMemoryPages = maxMemoryPages
+        self.maxCallStackDepth = maxCallStackDepth
+        self.maxExecutionSteps = maxExecutionSteps
+    }
+
+    /// Unlimited resource limits. Use with caution — a malicious module
+    /// can exhaust host resources when these limits are applied.
+    public static let unlimited = Limits(
+        maxMemoryPages: 65_536,
+        maxCallStackDepth: Int.max,
+        maxExecutionSteps: 0
+    )
+}
